mapper.select:
SELECT d.*, t.task_code, t.task_name
FROM quality_defect d LEFT JOIN quality_task t ON t.id = d.task_id
WHERE d.is_deleted = 0
AND d.task_id = #{taskId}
AND d.dispose_status = #{disposeStatus}
AND d.verify_status = #{verifyStatus}
AND d.image_id LIKE CONCAT('%',#{imageId},'%')
ORDER BY d.id DESC

mapper.update:
UPDATE quality_defect
updated_at = NOW(), dispose_status = #{disposeStatus}, verify_status = #{verifyStatus}, ignore_reason = #{ignoreReason}, updated_by = #{updatedBy}
WHERE id = #{id} AND is_deleted = 0
